const rows = parseCsv(readFileSync('sales.csv', 'utf8'));
const totals = new Map();
for (const row of rows) {
  const month = row.date.slice(0, 7);
  totals.set(month, (totals.get(month) ?? 0) + row.amount);
}

const summary = [...totals.entries()]
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([month, sales_total], idx, arr) => {
    const prev = idx > 0 ? arr[idx - 1][1] : null;
    const mom_growth_rate = prev === null || prev === 0 ? null : (sales_total - prev) / prev;

